mapper.select:
        select B.MENU_ID, B.PARENT_ID, B.NAME, B.ENAME,B.TYPE, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON,B.IMAGE_PATH, B.PRIORITY, B.CREATE_TIME
        from SYS_MENU B
        WHERE 1=1  AND B.TYPE = 'ADMIN' AND B.DEL_FLAG = 0


                AND B.APP_ID = #{currAppId}


				AND NAME like concat('%', #{menuName}, '%')


				AND IS_DISPLAY = #{visible}


				AND IS_DISABLED = #{status}


		order by PARENT_ID, PRIORITY

		select B.MENU_ID, B.PARENT_ID, B.NAME, B.ENAME,B.TYPE, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON,B.DEL_FLAG, B.PRIORITY, B.CREATE_TIME
		, (select COUNT(MENU_ID) from SYS_MENU where PARENT_ID = B.MENU_ID AND DEL_FLAG = 0) CHILD_NUM
		from SYS_MENU B
		WHERE 1=1  AND B.TYPE = 'ADMIN'

            AND B.APP_ID = #{currAppId}



                AND B.DEL_FLAG = #{delFlag}


                AND B.DEL_FLAG = 0



			AND B.URL_TYPE = #{menuType}



				AND NAME like concat('%', #{menuName}, '%')


				AND IS_DISPLAY = #{visible}


				AND IS_DISABLED = #{status}






						AND ( B.PARENT_ID = 0 OR B.PARENT_ID IS NULL )


						and B.PARENT_ID = #{parentId}




				AND (B.PARENT_ID = 0 OR B.PARENT_ID IS NULL)



			AND  (B.NAME like concat(concat('%',#{q}),'%')
			or B.ENAME like concat(concat('%',#{q}),'%')
			or B.MENU_SEQ like concat(concat('%',#{q}),'%')
			)

		order by PARENT_ID, PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B where B.URL_TYPE in ('CATAGORY', 'MENU') and B.IS_DISABLED = 0 AND B.TYPE = 'ADMIN' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
order by B.PARENT_ID, B.PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID left join ADMIN_USER_ROLE AUR on SRM.ROLE_ID = AUR.ROLE_ID left join SYS_ROLE ROLE on AUR.ROLE_ID = RO.ROLE_ID where AUR.ADMIN_ID = #{adminId} AND B.TYPE = 'ADMIN' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
AND B.NAME like concat('%', #{menuName}, '%')
AND B.IS_DISPLAY = #{visible}
AND B.IS_DISABLED = #{status}
order by B.PARENT_ID, B.PRIORITY

select distinct B.MENU_ID, B.PARENT_ID, B.NAME,B.TYPE, B.ENAME, B.MENU_SEQ, B.JS_EVENT, B.URL, B.IS_DISPLAY, B.IS_DISABLED, ifnull(B.PERMS,'') as PERMS, B.IS_CHECK, B.SPARE2,B.SPARE1, B.URL_TYPE, B.ICON, B.PRIORITY, B.CREATE_TIME from SYS_MENU B left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID left join ADMIN_USER_ROLE AUR on SRM.ROLE_ID = AUR.ROLE_ID left join SYS_ROLE RO on AUR.ROLE_ID = RO.ROLE_ID left join ADMIN_USER UR on AUR.ADMIN_ID = UR.ADMIN_ID where UR.ADMIN_ID = #{adminId} and B.URL_TYPE in ('CATAGORY', 'MENU') and B.IS_DISABLED = 0 AND RO.STATUS = 0 AND B.TYPE = 'ADMIN' AND B.DEL_FLAG = 0
AND B.APP_ID = #{currAppId}
order by B.PARENT_ID, B.PRIORITY

		select distinct B.PERMS
		from SYS_MENU B
			 left join SYS_ROLE_MENU SRM on B.MENU_ID = SRM.MENU_ID
		where B.IS_DISABLED = 0 AND B.TYPE = 'ADMIN' AND B.DEL_FLAG = 0 and SRM.ROLE_ID = #{roleId}

            AND B.APP_ID = #{currAppId}
